import{_ as s,a0 as o,w as d,s as a,ao as i,I as u,x as p,a1 as t,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"在ubuntu14.04上配置SNMPv3 | LCTT x X-CMD","titleTemplate":false,"description":"在ubuntu14.04上配置SNMPv3 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在ubuntu14.04上配置SNMPv3 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在ubuntu14.04上配置SNMPv3 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/How to configure SNMPv3 on ubuntu 14.04 server","title":"在ubuntu14.04上配置SNMPv3","tag":"201410","desc":""},"relativePath":"201410/How to configure SNMPv3 on ubuntu 14.04 server.md","filePath":"[post].md"}'),l={name:"201410/How to configure SNMPv3 on ubuntu 14.04 server.md"};function m(P,e,v,S,N,c){const n=o("Link");return d(),a("div",null,[e[11]||(e[11]=i(`<h1 id="在ubuntu14-04上配置snmpv3" tabindex="-1">在ubuntu14.04上配置SNMPv3 <a class="header-anchor" href="#在ubuntu14-04上配置snmpv3" aria-label="Permalink to “在ubuntu14.04上配置SNMPv3”">​</a></h1><p>简单网络管理协议（SNMP）是用于IP网络设备管理的标准协议。典型的支持SNMP协议的设备有路由器、交换机、服务器、工作站、打印机及数据机柜等等。SNMP一般被网络管理系统用于按照管理员设定的条件来监视网络附加设备。SNMP是因特网协议套件中的一个组成部分，它由IETF机构定义。它包含一系列的网络管理标准，其中有一个应用层协议，一个数据库架构以及一组数据对象。</p><p>SNMP将管理数据以变量的形式展示出来，这些变量描述了系统配置。同时这些变量可以被用于管理的应用查询（或者被设置）。</p><h3 id="为什么需要使用snmpv3" tabindex="-1">为什么需要使用SNMPv3 <a class="header-anchor" href="#为什么需要使用snmpv3" aria-label="Permalink to “为什么需要使用SNMPv3”">​</a></h3><p>尽管SNMPv3所增加的加密功能并不影响协议层面，但是新的文本惯例、概念及术语使得它看起来很不一样。</p><p>SNMPv3在SNMP的基础之上增强了安全性以及远程配置功能。</p><p>最初，SNMP最大的缺点就是安全性弱。SNMP的第一与第二个版本中，身份验证仅仅是在管理员与代理间传送一个明文的密码而已。目前每一个SNMPv3的信息都包含了被编码成8进制的安全参数。这些安全参数的具体意义由所选用的安全模型决定。</p><p>SNMPv3提供了重要的安全特性：</p><ul><li><p>保密性 —— 加密数据包以防止未经授权的源监听。</p></li><li><p>完整性 —— 数据的完整性特性确保数据在传输的时候没有被干扰，并且包含了可选的数据响应保护机制。</p></li><li><p>身份验证 —— 检查数据是否来自一个合法的源。</p></li></ul><h3 id="在ubuntu中安装snmp服务器及客户端" tabindex="-1">在ubuntu中安装SNMP服务器及客户端 <a class="header-anchor" href="#在ubuntu中安装snmp服务器及客户端" aria-label="Permalink to “在ubuntu中安装SNMP服务器及客户端”">​</a></h3><p>打开终端运行下列命令</p><pre><code>sudo apt-get install snmpd snmp
</code></pre><p>安装完成后需要做如下改变。</p><p>###配置SNMPv3###</p><p>获得从外部守护进程访问的权限</p><p>默认的安装仅提供本地的访问权限，如果想要获得外部访问权限，打开文件 /etc/default/snmpd。</p><pre><code>sudo vi /etc/default/snmpd
</code></pre><p>改变下列内容</p><p>将</p><pre><code>SNMPDOPTS=&#39;-Lsd -Lf /dev/null -u snmp -g snmp -I -smux,mteTrigger,mteTriggerConf -p /var/run/snmpd.pid&#39;
</code></pre><p>改为</p><pre><code>SNMPDOPTS=&#39;-Lsd -Lf /dev/null -u snmp -I -smux -p /var/run/snmpd.pid -c /etc/snmp/snmpd.conf&#39;
</code></pre><p>最后重启 snmpd</p><pre><code>sudo /etc/init.d/snmpd restart
</code></pre><p>###定义 SNMPv3 用户，身份验证以及加密参数 ###</p><p>“securityLevel”参数使得SNMPv3有多种不同的用途。</p><ul><li><p>noAuthNoPriv —— 没有授权，加密以及任何安全保护！</p></li><li><p>authNoPriv —— 需要身份认证，但是不对通过网络发送的数据进行加密。</p></li><li><p>autoPriv —— 最可靠模式。需要身份认证而且数据会被加密。</p></li></ul><p>snmpd 的配置以及设置都保存在文件 /etc/snmp/snmpd.conf。使用编辑器编辑文件：</p><pre><code>sudo vi /etc/snmp/snmpd.conf
</code></pre><p>在文件末尾添加以下内容：</p><pre><code>#
createUser user1
createUser user2 MD5 user2password
createUser user3 MD5 user3password DES user3encryption
#
rouser user1 noauth 1.3.6.1.2.1.1
rouser user2 auth 1.3.6.1.2.1
rwuser user3 priv 1.3.6.1.2.1
</code></pre><p>注：如果你需要使用自己的用户名/密码对的话，请注意密码及加密短语的最小长度是8个字符。</p><p>同时，你需要做如下的配置以便snmp可以监听来自任何接口的连接请求。</p><p>将</p><pre><code>#agentAddress udp:161,udp6:[::1]:161
</code></pre><p>改为</p><pre><code>agentAddress udp:161,udp6:[::1]:161
</code></pre><p>保存改变后的snmpd.conf文件并且重启守护进程：</p><pre><code>sudo /etc/init.d/snmpd restart
</code></pre><hr>`,40)),u("p",null,[e[1]||(e[1]=p("via: ",-1)),t(n,{href:"http://www.ubuntugeek.com/how-to-configure-snmpv3-on-ubuntu-14-04-server.html"},{default:r(()=>[...e[0]||(e[0]=[p("http://www.ubuntugeek.com/how-to-configure-snmpv3-on-ubuntu-14-04-server.html",-1)])]),_:1})]),u("p",null,[e[4]||(e[4]=p("译者：",-1)),t(n,{href:"https://github.com/SPccman"},{default:r(()=>[...e[2]||(e[2]=[p("SPccman",-1)])]),_:1}),e[5]||(e[5]=p(" 校对：",-1)),t(n,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...e[3]||(e[3]=[p("Caroline",-1)])]),_:1})]),u("p",null,[e[8]||(e[8]=p("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[6]||(e[6]=[p("LCTT",-1)])]),_:1}),e[9]||(e[9]=p(" 原创翻译，",-1)),t(n,{href:"http://linux.cn/"},{default:r(()=>[...e[7]||(e[7]=[p("Linux中国",-1)])]),_:1}),e[10]||(e[10]=p(" 荣誉推出",-1))])])}const T=s(l,[["render",m]]);export{b as __pageData,T as default};
